/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `limit_course_num` BEFORE INSERT ON `class_task` FOR EACH ROW begin
    declare exist_num integer;
    set exist_num = (select SUM(ct.weeks_number)
        FROM class_task ct
        WHERE NEW.class_no = ct.class_no
        );
    IF exist_num + NEW.weeks_number > 30
    THEN DELETE FROM class_task clt
            WHERE NEW.id = clt.id;
    END IF;
    IF NEW.isFix = 2
    THEN IF (NEW.class_time = '01' or NEW.class_time = '02' or NEW.class_time = '03' or NEW.class_time = '04' or NEW.class_time = '05'
          or NEW.class_time = '06' or NEW.class_time = '07' or NEW.class_time = '08' or NEW.class_time = '09' or NEW.class_time = '10'
          or NEW.class_time = '11' or NEW.class_time = '12' or NEW.class_time = '13' or NEW.class_time = '14' or NEW.class_time = '15'
          or NEW.class_time = '16' or NEW.class_time = '17' or NEW.class_time = '18' or NEW.class_time = '19' or NEW.class_time = '20'
          or NEW.class_time = '21' or NEW.class_time = '22' or NEW.class_time = '23' or NEW.class_time = '24' or NEW.class_time = '25'
          or NEW.class_time = '26' or NEW.class_time = '27' or NEW.class_time = '28' or NEW.class_time = '29' or NEW.class_time = '30'
        ) = FALSE
         THEN set NEW.isFix = 1;
              set NEW.class_time =NULL;
         end if;
    end if;
end */;;
DELIMITER ;
