--
-- Table structure for table `course_plan`
--

DROP TABLE IF EXISTS `course_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_plan` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `grade_no` varchar(2) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL COMMENT '年级编号',
  `class_no` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL COMMENT '班级编号',
  `course_no` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL COMMENT '课程编号',
  `teacher_no` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL COMMENT '讲师编号',
  `classroom_no` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL COMMENT '教室编号',
  `class_time` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL COMMENT '上课时间',
  `weeks_sum` int DEFAULT NULL COMMENT '周数',
  `semester` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8_general_ci DEFAULT NULL COMMENT '学期',
  `deleted` tinyint(1) DEFAULT '0',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `grade_no` (`grade_no`) USING BTREE,
  KEY `class_number` (`class_no`) USING BTREE,
  KEY `course_no` (`course_no`) USING BTREE,
  KEY `teacher_number` (`teacher_no`) USING BTREE,
  KEY `classroom_no` (`classroom_no`) USING BTREE,
  CONSTRAINT `class_number` FOREIGN KEY (`class_no`) REFERENCES `class_information` (`class_no`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `classroom_no` FOREIGN KEY (`classroom_no`) REFERENCES `classroom` (`classroom_no`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `course_no` FOREIGN KEY (`course_no`) REFERENCES `course_information` (`course_no`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `grade_no` FOREIGN KEY (`grade_no`) REFERENCES `grade_information` (`grade_no`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `teacher_number` FOREIGN KEY (`teacher_no`) REFERENCES `teacher` (`teacher_no`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=142 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

