/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `insert_plan_unique` BEFORE INSERT ON `course_plan` FOR EACH ROW begin
    declare num,num1 integer;
    declare room varchar(20);
    set num = (
        SELECT COUNT(*)
        FROM course_plan cp1
        WHERE NEW.class_time = cp1.class_time and cp1.deleted = 0
          and(
                    NEW.class_no = cp1.class_no or
                    NEW.teacher_no = cp1.teacher_no
            )
    );
    IF num > 0
    THEN SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'class or teacher is busy';
    END IF;

    set num1 =(
        SELECT COUNT(*)
        FROM course_plan
        WHERE NEW.class_time = course_plan.class_time and course_plan.deleted = 0
              and NEW.classroom_no = course_plan.classroom_no
        );

    set room =(
        select cpcn1.classroom_no
        FROM (select classroom_no from classroom where classroom.deleted = 0) as cpcn1
                 LEFT JOIN (select classroom_no cn FROM course_plan WHERE NEW.class_time = course_plan.class_time and course_plan.deleted = 0) as cpcn2
                           ON cpcn1.classroom_no = cpcn2.cn
        WHERE cpcn2.cn is NULL
        ORDER BY RAND() LIMIT 1
    );

    IF room is not NULL and num1 > 0
    THEN
        SET NEW.classroom_no = room;
    END IF;

    IF room is null and num1 > 0
    THEN SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'classroom is busy';
    END IF;


end */;;
DELIMITER ;
